def wikipedia_search_wikipedia(query, limit=10, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0157000" if __import__("os").path.isdir("./environment_mix/0157000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "Missing or empty query.")
    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Invalid limit: must be an integer.")
    if limit <= 0:
        return _err("VALIDATION_ERROR", "Invalid limit: must be positive.")
    if limit > 50:
        return _err("VALIDATION_ERROR", "Invalid limit: too large for a single request.", max_limit=50)

    # Load store (0 rows in this service snapshot; handle both list and dict forms)
    data = _load("wikipedia.json")
    articles = []
    if isinstance(data, dict) and isinstance(data.get("articles"), dict):
        for v in data["articles"].values():
            if isinstance(v, dict):
                articles.append(v)
    elif isinstance(data, list):
        # If stored as list of rows with an "articles" object field
        for row in data:
            if isinstance(row, dict) and isinstance(row.get("articles"), dict):
                for v in row["articles"].values():
                    if isinstance(v, dict):
                        articles.append(v)

    q = query.strip().lower()

    def _score(a):
        t = (a.get("title") or "")
        s = (a.get("summary") or "")
        tl = t.lower()
        sl = s.lower()
        if tl == q:
            return 0
        if tl.startswith(q):
            return 1
        if q in tl:
            return 2
        if q in sl:
            return 3
        return 4

    matches = []
    for a in articles:
        t = a.get("title") or ""
        s = a.get("summary") or ""
        if not isinstance(t, str) or not t.strip():
            continue
        tl = t.lower()
        sl = s.lower() if isinstance(s, str) else ""
        if q in tl or (sl and q in sl):
            snippet = s if isinstance(s, str) else ""
            if len(snippet) > 180:
                snippet = snippet[:177] + "..."
            matches.append({"title": t, "snippet": snippet})

    # Sort and limit
    matches_sorted = sorted(matches, key=lambda r: (_score({"title": r["title"], "summary": r.get("snippet", "")}), r["title"].lower()))
    results = matches_sorted[:limit]

    return {
        "query": query,
        "limit": limit,
        "results": results,
        "total": len(matches_sorted),
        "has_more": len(matches_sorted) > limit
    }

def wikipedia_get_article(title, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0157000" if __import__("os").path.isdir("./environment_mix/0157000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "Missing or empty title.")

    data = _load("wikipedia.json")

    def _iter_articles(d):
        if isinstance(d, dict) and isinstance(d.get("articles"), dict):
            for v in d["articles"].values():
                if isinstance(v, dict):
                    yield v
        elif isinstance(d, list):
            for row in d:
                if isinstance(row, dict) and isinstance(row.get("articles"), dict):
                    for v in row["articles"].values():
                        if isinstance(v, dict):
                            yield v

    want = title.strip()
    want_l = want.lower()

    found = None
    for a in _iter_articles(data):
        t = a.get("title")
        if isinstance(t, str) and t.strip().lower() == want_l:
            found = a
            break

    if not found:
        return _err("NOT_FOUND", "Title does not resolve to an article.", title=title)

    summary = found.get("summary") if isinstance(found.get("summary"), str) else ""
    sections = found.get("sections") if isinstance(found.get("sections"), dict) else {}
    links = found.get("links") if isinstance(found.get("links"), list) else []
    key_facts = found.get("key_facts") if isinstance(found.get("key_facts"), list) else []

    # Build content in a deterministic order (insertion order of dict as stored)
    parts = []
    if summary:
        parts.append(summary.strip())
    for k, v in sections.items():
        if isinstance(k, str) and isinstance(v, str):
            parts.append(f"{k}\n{v}".strip())
    content = "\n\n".join([p for p in parts if p])

    return {
        "title": found.get("title", want),
        "summary": summary,
        "sections": sections,
        "links": links,
        "key_facts": key_facts,
        "content": content
    }

