def wikipedia_summarize_article_for_query(title, query, max_length=250, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0157000" if __import__("os").path.isdir("./environment_mix/0157000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "Missing or empty title.")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "Missing or empty query.")
    if max_length is None:
        max_length = 250
    if not isinstance(max_length, int):
        return _err("VALIDATION_ERROR", "Invalid max_length: must be an integer.")
    if max_length <= 0:
        return _err("VALIDATION_ERROR", "Invalid max_length: must be positive.")
    if max_length > 1000:
        return _err("VALIDATION_ERROR", "Invalid max_length: too large.", max_max_length=1000)

    data = _load("wikipedia.json")
    want = title.strip().lower()
    found = None

    def _iter_articles(d):
        if isinstance(d, dict) and isinstance(d.get("articles"), dict):
            for v in d["articles"].values():
                if isinstance(v, dict):
                    yield v
        elif isinstance(d, list):
            for row in d:
                if isinstance(row, dict) and isinstance(row.get("articles"), dict):
                    for v in row["articles"].values():
                        if isinstance(v, dict):
                            yield v

    for a in _iter_articles(data):
        t = a.get("title")
        if isinstance(t, str) and t.strip().lower() == want:
            found = a
            break

    if not found:
        return _err("NOT_FOUND", "Title does not resolve to an article.", title=title)

    q = query.strip().lower()
    summary = found.get("summary") if isinstance(found.get("summary"), str) else ""
    sections = found.get("sections") if isinstance(found.get("sections"), dict) else {}

    # Very simple query-focused extraction: prefer sentences/section text containing query terms.
    base_texts = []
    if summary:
        base_texts.append(summary)
    for k, v in sections.items():
        if isinstance(k, str) and isinstance(v, str):
            base_texts.append(f"{k}: {v}")

    text = "\n".join(base_texts).strip()

    def _sentences(s):
        # lightweight sentence split
        out = []
        buf = []
        for ch in s:
            buf.append(ch)
            if ch in ".!?":
                seg = "".join(buf).strip()
                if seg:
                    out.append(seg)
                buf = []
        tail = "".join(buf).strip()
        if tail:
            out.append(tail)
        return out

    hits = []
    for seg in _sentences(text):
        sl = seg.lower()
        if q in sl:
            hits.append(seg)

    if hits:
        out_text = " ".join(hits)
    else:
        out_text = summary or text

    out_text = out_text.strip()
    if len(out_text) > max_length:
        out_text = out_text[: max_length - 3].rstrip() + "..." if max_length >= 4 else out_text[:max_length]

    return {"title": found.get("title", title.strip()), "query": query, "summary": out_text, "max_length": max_length}

