def wikipedia_extract_key_facts(title, topic_within_article="", count=5, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0157000" if __import__("os").path.isdir("./environment_mix/0157000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "Missing or empty title.")
    if topic_within_article is None:
        topic_within_article = ""
    if not isinstance(topic_within_article, str):
        return _err("VALIDATION_ERROR", "Invalid topic_within_article: must be a string.")
    if count is None:
        count = 5
    if not isinstance(count, int):
        return _err("VALIDATION_ERROR", "Invalid count: must be an integer.")
    if count <= 0:
        return _err("VALIDATION_ERROR", "Invalid count: must be positive.")
    if count > 25:
        return _err("VALIDATION_ERROR", "Invalid count: too large.", max_count=25)

    data = _load("wikipedia.json")
    want = title.strip().lower()

    found = None
    if isinstance(data, dict) and isinstance(data.get("articles"), dict):
        for a in data["articles"].values():
            if isinstance(a, dict) and isinstance(a.get("title"), str) and a["title"].strip().lower() == want:
                found = a
                break
    elif isinstance(data, list):
        for row in data:
            if isinstance(row, dict) and isinstance(row.get("articles"), dict):
                for a in row["articles"].values():
                    if isinstance(a, dict) and isinstance(a.get("title"), str) and a["title"].strip().lower() == want:
                        found = a
                        break
            if found:
                break

    if not found:
        return _err("NOT_FOUND", "Title does not resolve to an article.", title=title)

    facts = found.get("key_facts")
    if not isinstance(facts, list):
        facts = []

    # Optional topic scoping: only accept if it matches a section title; otherwise refuse (as tool may refuse)
    scoped_facts = facts
    if topic_within_article.strip():
        sections = found.get("sections") if isinstance(found.get("sections"), dict) else {}
        topic_l = topic_within_article.strip().lower()
        sec_match = None
        for k in sections.keys():
            if isinstance(k, str) and k.strip().lower() == topic_l:
                sec_match = k
                break
        if sec_match is None:
            return _err("NOT_FOUND", "topic_within_article cannot be matched to a section in the article.", title=title, topic_within_article=topic_within_article)
        # If we had structured per-section facts we'd filter; here we just return top facts (best available)
        scoped_facts = facts

    items = []
    for i, f in enumerate(scoped_facts[:count], start=1):
        if isinstance(f, str):
            items.append({"index": i, "fact": f})
        else:
            items.append({"index": i, "fact": str(f)})

    return {
        "title": found.get("title", title.strip()),
        "topic_within_article": topic_within_article,
        "count": count,
        "key_facts": items
    }

