    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "Missing or empty title.")
    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Invalid limit: must be an integer.")
    if limit <= 0:
        return _err("VALIDATION_ERROR", "Invalid limit: must be positive.")
    if limit > 50:
        return _err("VALIDATION_ERROR", "Invalid limit: too large.", max_limit=50)

    data = _load("wikipedia.json")
    want = title.strip().lower()

    found = None
    if isinstance(data, dict) and isinstance(data.get("articles"), dict):
        for a in data["articles"].values():
            if isinstance(a, dict) and isinstance(a.get("title"), str) and a["title"].strip().lower() == want:
                found = a
                break
    elif isinstance(data, list):
        for row in data:
            if isinstance(row, dict) and isinstance(row.get("articles"), dict):
                for a in row["articles"].values():
                    if isinstance(a, dict) and isinstance(a.get("title"), str) and a["title"].strip().lower() == want:
                        found = a
                        break
            if found:
                break

    if not found:
        return _err("NOT_FOUND", "Title does not resolve to an article.", title=title)

    links = found.get("links")
    if not isinstance(links, list):
        links = []

    # De-duplicate while preserving order
    seen = set()
    related = []
    for x in links:
        if not isinstance(x, str):
            continue
        k = x.strip()
        if not k:
            continue
        kl = k.lower()
